export interface TaintSinkRecord {
    taintId: number;
    sinkType: SinkType;
    sourceDef: Def;
    astNode: Node;
    remark?: string;
    urlTaintControl?: UrlTaintControl;
}
export interface TaintSanitizerRecord {
    taintId: number;
    sanitizerName: string;
    def: Def;
    astNode: Node;
}
export interface TaintSource {
    taintId: number;
    sourceType: SourceType;
    originDefId: number;
    isPseudo: boolean;
    remark?: string;
}
export interface TaintPathRecord {
    taintId: number;
    fromDef: Def;
    toDef: Def;
    astNode: Node;
    PropagateType: PropagateType;
    remark: string;
}
export interface TaintAnalysisSummary {
    hasTaint: boolean;
    hasSink: boolean;
    totalSources: number;
    totalSinks: number;
}
export interface OuterSourceRecord {
    taintId: number;
    outer?: string;
    channel: string;
    astNode: Node;
    originDefId?: number;
    autoPushed?: boolean;
}
export interface OuterSinkRecord extends TaintSinkRecord {
    outer?: string;
    channel?: string;
}
export interface DeferredMessageInvoke {
    callNode: FlowNode;
    astNode: Node;
    invoke: (message: Def) => void;
}
export interface PseudoTaintReceiver {
    taintId: number;
    contextFilename: string;
    astNode: Node;
    channel: string;
    targetDef: Def;
    outer?: string;
    deferredMessage?: DeferredMessageInvoke;
}
